import React, {Component} from "react";
import Navbar from "./Navbar";
import axios from "axios";
import {Link, Redirect} from "react-router-dom";
import {SERVER_HOST} from "../config/global_constants";

class Login extends Component {
    constructor(props) {
        super(props);
        this.state = {
            loginEmail: '',
            loginPassword: '',
            error: '',
            isLoggedIn: false,
            redirectURL: "/MainPage",
        };
    }

    handleLogin = async (e) => {
        e.preventDefault();
        console.log('Login with:', this.state.loginEmail, this.state.loginPassword);

        try {
            axios.post(`${SERVER_HOST}/users/login/${this.state.email}/${this.state.password}`)
                .then(res => {
                    if (res.data) {
                        if (res.data.errorMessage) {
                            console.log("adfs")
                        } else {
                            console.log("User logged in");
                            alert('Login successful');

                            localStorage.name = res.data.name
                            localStorage.accessLevel = res.data.accessLevel
                            localStorage.token = res.data.token
                            localStorage.role = res.data.role

                            this.setState({isLoggedIn: true, redirectURL: res.data.redirectURL})
                        }
                    }
                })
        } catch (error) {
            console.error('Login error:', error.response?.data || error.message);
            this.setState({errors: {general: error.response?.data?.error || "Login failed. Please check your credentials."}});
        }
    };


    render() {
        if (this.state.isLoggedIn) {
            return <Redirect to={this.state.redirectURL}/>;
        }
        return (
            <div>
                <div className="login">
                    <div className="login-container">
                        {/* Login Form */}
                        <form onSubmit={this.handleLogin}>
                            <h2>Login</h2>
                            <div className="input-group">
                                <label>
                                    Email Address *
                                    <input
                                        type="email"
                                        value={this.state.loginEmail}
                                        onChange={e => this.setState({loginEmail: e.target.value})}
                                        required
                                    />
                                </label>
                                <label>
                                    Password *
                                    <input
                                        type="password"
                                        value={this.state.loginPassword}
                                        onChange={e => this.setState({loginPassword: e.target.value})}
                                        required
                                    />
                                </label>
                                <div>
                                    <input type="checkbox"/> Remember Me
                                </div>
                                <button type="submit">Log in</button>
                                <a href="#">Lost your password?</a>
                            </div>
                        </form>


                        {/* Additional Links */}
                        <div style={{marginLeft: 20}}>
                            <p>Don't have an account?</p>
                            <Link to="/Register">Register</Link>
                            <br/><br/>
                            <p>Or, sign in as Admin</p>
                            <Link to="/AdminLogin">Admin Login</Link>

                        </div>
                    </div>
                </div>
            </div>
        );
    }
}

export default Login;
